def transform_grid_v2(grid):
    result = [row[:] for row in grid]  # deep copy

    # Region bounds: r[13..18], c[5..9]
    min_r, max_r = 13, 18
    min_c, max_c = 5, 9

    # Fill region with 4s
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            result[r][c] = 4

    # Leave scattered 2s alone

    return result

candidate_v2 = transform_grid_v2(grid)

# Check 2s are preserved
for r in range(28):
    for c in range(15):
        if grid[r][c] == 2 and candidate_v2[r][c] == 9:
            print(f"ERROR: Changed 2 at ({r},{c})")

print("Checking preservation of 2s...")
preserved_2s = 0
changed_2s = 0
for r in range(28):
    for c in range(15):
        if grid[r][c] == 2:
            if candidate_v2[r][c] == 2:
                preserved_2s += 1
            else:
                changed_2s += 1

print(f"Preserved: {preserved_2s}, Changed: {changed_2s}")

print("\nCandidate output (rows with 2s):")
# Find rows with 2s in candidate
for r in range(28):
    has_2 = any(candidate_v2[r][c] == 2 for c in range(15))
    if has_2:
        print(f"Row {r}: {candidate_v2[r]}")

print("\nRegion rows 13-18:")
for r in range(13, 19):
    print(f"Row {r} (cols 0-14): {candidate_v2[r]}")

